//! 🧪️ Canonical retained framing matches the existing writer without allocating or changing original payload storage.
use super::*;
#[global_allocator]static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
struct Source{rows:Vec<(u8,bool,Vec<u8>)>}
impl BorrowedSprSource for Source{fn source_identity(&self)->usize{self as*const _ as usize}fn record(&self,index:usize)->Result<Option<BorrowedSprRecord<'_>>,ValueError>{Ok(self.rows.get(index).map(|(kind,critical,payload)|BorrowedSprRecord{kind:*kind,critical:*critical,payload}))}}
fn full(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn denials(d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut list=vec![RetainedCloneGrant{maximum_items:0,..full(d)}];if d.copy_bytes!=0{list.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..full(d)});}if d.depth!=0{list.push(RetainedCloneGrant{maximum_depth:d.depth-1,..full(d)});}list}
#[semio_framework_async_macros::async_test]
async fn original_spr_file_matches_canonical_reference_and_exact_bounded_work(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let source=Source{rows:law["records"].as_array().unwrap().iter().map(|row|(row["kind"].as_u64().unwrap()as u8,row["critical"].as_bool().unwrap(),row["text"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap_or(1)as usize).into_bytes())).collect()};let pointers:Vec<_>=source.rows.iter().map(|row|row.2.as_ptr()).collect();let mut writer=SprWriter::begin(Vec::new(),&WriteOptions{required_flags:semio_framework_replication_wire_core::REQUIRED_HASH_CHAIN,optional_flags:semio_framework_replication_wire_core::OPTIONAL_CANONICAL}).await.unwrap();for(kind,critical,payload)in &source.rows{writer.write_record(*kind,*critical,payload,semio_framework_replication_codec::CodecId(0)).await.unwrap();}writer.commit().await.unwrap();let expected=writer.into_sink().await;
 for width in law["widths"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as usize){for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){let mut cursor=BorrowedSprFileCursor::default();let mut output=Vec::new();let epoch=law["epoch"].as_u64().unwrap();for turn in 0..1000000{if cut==Some(turn)||cursor.is_complete(){break}let d=cursor.next_demands();for denied in denials(d){let mut bytes=[73;64];let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&source,epoch,&mut bytes[..width],denied).unwrap());assert_eq!((step.written,step.progress),(0,Default::default()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(bytes,[73;64]);}let mut bytes=[0;64];let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&source,epoch,&mut bytes[..width],full(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(step.progress.fits(full(d)));assert!(step.written<=width.min(64));output.extend_from_slice(&bytes[..step.written]);let mut untouched=[73;64];let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&source,epoch+1,&mut untouched[..width],full(d)));assert!(error.is_err());assert_eq!(untouched,[73;64]);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(turn<999999);}if cut.is_none(){assert!(cursor.is_complete());assert_eq!(output,expected);if let Some(path)=std::env::var_os("ENERGY_SPR_EXPORT_ORACLE"){std::fs::write(path,&output).unwrap();}}let d=cursor.close_demands();for denied in denials(d){assert_eq!(cursor.close(denied).progress(),Default::default());assert!(!cursor.terminal_is_empty());}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close(full(d)));assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(cursor.terminal_is_empty());assert_eq!(source.rows.iter().map(|row|row.2.as_ptr()).collect::<Vec<_>>(),pointers);}}
}
